import React, { useState, useEffect } from "react";
import $ from "jquery";
import { GrClose } from "react-icons/gr";
import { Navigate, useLocation, useNavigate } from "react-router-dom";
import "../Assets/css/dashboard.css";
import Analytics from "./Analytics";
import Home from "./Home";
import UserDetail from "./UserDetails";
import Navbar from "../seperate/Navbar";
import Footer from "../seperate/Footer";
import { BiSolidUserDetail } from "react-icons/bi";
import Userlist from "./Userlist";
import { MdSwitchAccount } from "react-icons/md";
import Withdrawrequest from "./Withdrawrequest";
import Transaction from "./Transaction";
import { GiTwoCoins } from "react-icons/gi";
import Spotpair from "./Spotpair";
import Sitesetting from "./Sitesetting";
import Orderhistory from "./Orderhistory";
import Tradehistory from "./TradeHistory";
import CryptoAndFiat from "./CryptoAndFiat";
import AdminTransfer from "./AdminTransfer";
import Nofitication from "./Nofitication";
import Adminsetting from "./Adminsetting";
import { MdNotificationImportant } from "react-icons/md";
import { MdTransferWithinAStation } from "react-icons/md";
import { GoGitPullRequest } from "react-icons/go";
import { GrTransaction } from "react-icons/gr";
import { IoSettingsOutline } from "react-icons/io5";
import { IoSettingsSharp } from "react-icons/io5";
import { SiGnuprivacyguard } from "react-icons/si";

import SwapHistory from "./Swap_history";
import { Link } from "react-router-dom";
import { FaHistory, FaTicketAlt } from "react-icons/fa";
import { MdHistoryEdu } from "react-icons/md";
import TermsConditons from "../seperate/TermsConditonsPage/TermsConditons";
import SubminPage from "../seperate/Subadmin/SubadminPage";
import CreateSubAdmin from "../seperate/Subadmin/CreateSubAdmin";
import EditSubAdmin from "../seperate/Subadmin/EditSubAdmin";
import { toast, ToastContainer } from "react-toastify";
import { makeApiRequest } from "../axiosService/ApiCall";
import { BsFilePerson } from "react-icons/bs";
import SupportTicket from "./Support/SupportTicket";
import AdminActivity from "./Subadmin/AdminActivity";
import NoAccess from "./Subadmin/NoAccess";
import SubadminLoginPage from "./Subadmin/SubadminLoginPage";
import { AiOutlineDatabase } from "react-icons/ai";

$(document).ready(function () {
  if ($(window).width() < 600) {
    // if width is less than 600px
    $(".nav-link").click(function () {
      $("#mySidenav").css("width", "0px");
    });
  } else {
    // $('#v-pills-asset-tab').click(function () {
    //   location.reload();
    // });
  }

  $(".dashboard-profile-table-tabs-section-hide").hide();
  $(".details-button-navigation button").click(function () {
    $(".dashboard-profile-section-hide").hide();
    $(".dashboard-profile-table-tabs-section-hide").show();
    $("#mySidenav").css("width", "100px");
    $(".dashboard-main-section").css("margin-left", "100px");
    $(".dashboard-navbar-brand img").css("width", "50px");
    $(".dashboard-navbar-brand img").css("height", "50px");
    $("#mobile-close-arrow-left").hide();
    $(".dashboard-text-1").hide();
    $("#mobile-close-arrow-right").show();
  });
  $(".button-dashboard-table-back").click(function () {
    $(".dashboard-profile-section-hide").show();
    $(".dashboard-profile-table-tabs-section-hide").hide();
    $("#mySidenav").css("width", "250px");
    $(".dashboard-main-section").css("margin-left", "250px");
    $(".dashboard-navbar-brand img").css("width", "80px");
    $(".dashboard-navbar-brand img").css("height", "80px");
    $("#mobile-close-arrow-left").show();
    $(".dashboard-text-1").show();
    $("#mobile-close-arrow-right").hide();
  });
  $("#mobile-close-arrow-right").hide();
  $("#mobile-close-arrow-left").click(function () {
    $("#mySidenav").css("width", "100px");
    $(".dashboard-main-section").css("margin-left", "100px");
    $(".dashboard-navbar-brand img").css("width", "50px");
    $(".dashboard-navbar-brand img").css("height", "50px");
    $("#mobile-close-arrow-left").hide();
    $(".dashboard-text-1").hide();
    $("#mobile-close-arrow-right").show();
  });
  $("#mobile-close-arrow-right").click(function () {
    $("#mySidenav").css("width", "250px");
    $(".dashboard-main-section").css("margin-left", "250px");
    $(".dashboard-navbar-brand img").css("width", "80px");
    $(".dashboard-navbar-brand img").css("height", "80px");
    $("#mobile-close-arrow-left").show();
    $(".dashboard-text-1").show();
    $("#mobile-close-arrow-right").hide();
  });
  if ($("#mySidenav").css("width") === "100px") {
    $("#mySidenav").css("a");
  }
});

function Dashboard({ pageName }) {
  const [totalViewData, setTotalViewData] = useState([]);
  // console.log("totalViewData", totalViewData);
  const [adminType, setAdminType] = useState("");
  // console.log("adminType", adminType);
  const location = useLocation();
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    vieweditres();
  }, []);
  const vieweditres = async () => {
    try {
      let params = {
        url: "view-edit-GetData",
        method: "get",
        headers: {
          Authorization: `Bearer ${localStorage.getItem("token")}`,
        },
      };
      const vieweditres = await makeApiRequest(params);
      // console.log("vieweditres>>>", vieweditres);
      // return
      if (vieweditres.status == true) {
        const response = vieweditres?.data?.adminPermissions;

        setTotalViewData(response);
        if (response && Object.keys(response).length > 0) {
          setAdminType(vieweditres.data.admin_type);
        }
      } else if (vieweditres.status == false) {
        console.log(vieweditres.message);
        // toast.error(vieweditres.message);
      }
    } catch (error) {
      console.log("err", error);
    }
  };

  // const [token,setToken] = useState(null);
  // const navigate = useNavigate();
  // useEffect(() => {
  //     const token = localStorage.getItem("AdminCredentials");
  //     if (token) {
  //         navigate("/dashboard/admin-transfer");
  //     } else {
  //         navigate("/");
  //     }
  //     setToken(token)
  // }, [token])
  useEffect(() => {
    $("#mobile-three-line-collapse").click(function () {
      $("#mySidenav").css("width", "250px");
      // console.log("Mobile three line collapse clicked");
    });
    $("#mobile-close-collapse").click(function () {
      $("#mySidenav").css("width", "0px");
    });
  });
  //  if (loading) {
  //   return (
  //     <div className="d-flex justify-content-center align-items-center vh-100">
  //       <Spinner animation="border" />
  //     </div>
  //   )
  // }

  return (
    <div>
      <ToastContainer />
      <Navbar />
      <div className="App dashboard-navhide-section">
        <div className="container-fluid">
          <div className="d-flex flex-lg-row flex-column">
            {/* Sidebar */}
            <div>
              <span id="mobile-three-line-collapse" style={{ fontSize: "24px" }}>&#9776;</span>
              <div className="dashboard-sidenav-section" id="mySidenav">
                <nav
                  id="sidebar"
                  className="col-md-12 col-lg-12 d-md-block sidebar component-navbar"
                >
                  <div className="d-flex flex-row">
                    <div className="ms-auto me-3">
                      <span id="mobile-close-collapse">
                        <GrClose />
                      </span>
                    </div>
                  </div>

                  {/*<div className="d-flex flex-row pt-2 mb-2">
                    <div className="mx-auto">
                      <a className="navbar-brand" href="/"><img src={render12}></img></a> 
                    </div>
                  </div>*/}

                  <div>
                    <ul className="nav flex-column nav-pills">
                      {adminType == "SuperAdmin" && (
                        <li className="nav-item">
                          <Link
                            className={`nav-link component-tabs ${location.pathname === "/dashboard/admin-transfer"
                                ? "active"
                                : ""
                              }`}
                            to="/dashboard/admin-transfer"
                          >
                            <MdTransferWithinAStation className="sidenav-icon-size-css" />{" "}
                            Admin Transfer
                          </Link>
                        </li>
                      )}
                      {/* accounts */}

                      {(totalViewData?.accounts?.View === 1 ||
                        adminType == "SuperAdmin") && (
                          <li className="nav-item">
                            <Link
                              className={`nav-link component-tabs ${location.pathname === "/dashboard/user-list"
                                  ? "active"
                                  : ""
                                }`}
                              to="/dashboard/user-list"
                            >
                              <MdSwitchAccount className="sidenav-icon-size-css " />{" "}
                              Accounts
                            </Link>
                          </li>
                        )}
                      {/* pairList */}
                      {(totalViewData?.pairList?.View === 1 ||
                        adminType == "SuperAdmin") && (
                          <li className="nav-item">
